  "home.fact2.title": "\u0639\u0645\u0631 6-9 \u0633\u0646\u0648\u0627\u062a \u064a\u0636\u0627\u0639\u0641 \u0627\u0644\u062e\u0637\u0631 \u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062a",
