  "hors_ecole": "\u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629",
  "indicateurs.eyebrow": "\u0645\u0635\u0641\u0648\u0641\u0629 \u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637 \u00b7 \u0628\u064a\u0631\u0633\u0648\u0646",
  "indicateurs.heatmap_sub": "\u0627\u0644\u0623\u062e\u0636\u0631 = \u0627\u0631\u062a\u0628\u0627\u0637 \u0633\u0644\u0628\u064a\u060c \u0627\u0644\u0628\u0631\u062a\u0642\u0627\u0644\u064a = \u0625\u064a\u062c\u0627\u0628\u064a\u060c \u0627\u0644\u0623\u0633\u0648\u062f = \u0645\u062d\u0627\u064a\u062f. \u0627\u0642\u0631\u0623 \u0627\u0644\u0645\u062b\u0644\u062b \u0627\u0644\u0633\u0641\u0644\u064a \u0641\u0642\u0637 (\u0627\u0644\u0635\u0648\u0631\u0629 \u0645\u062a\u0646\u0627\u0638\u0631\u0629).",
  "indicateurs.heatmap_title": "\u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0627\u0631\u062a\u0628\u0627\u0637 \u0627\u0644\u062d\u0631\u0627\u0631\u064a\u0629: 12 \u0645\u0624\u0634\u0631\u064b\u0627 \u00d7 13 \u0648\u0644\u0627\u064a\u0629",
  "indicateurs.insight1.text": "\u0645\u0639\u062f\u0644 \u0627\u0644\u062e\u0631\u0648\u062c \u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u062a\u062d\u0645\u0644\u0647 \u0646\u0633\u0628\u0629 \u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0634\u0628\u0627\u0628\u064a (0-14 / 15-64)\u060c \u0648\u0647\u064a \u0628\u062f\u0648\u0631\u0647\u0627 \u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0631\u064a\u0641\u064a\u0629: \u0627\u0644\u0623\u0633\u0631\u0629 \u0627\u0644\u0631\u064a\u0641\u064a\u0629 \u0627\u0644\u0643\u0628\u064a\u0631\u0629 \u0648\u0627\u0644\u0641\u0642\u064a\u0631\u0629 \u0647\u064a \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0628\u0646\u064a\u0648\u064a.",
  "indicateurs.insight1.title": "\u0627\u0644\u0631\u064a\u0641\u064a\u0629 \u0647\u064a \u0627\u0644\u0623\u0633\u0627\u0633",
  "indicateurs.insight2.text": "\u0646\u0633\u0628\u0629 0-14 \u0633\u0646\u0629 \u0648\u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0634\u0628\u0627\u0628\u064a \u0645\u062a\u0631\u0627\u0628\u0637\u062a\u0627\u0646 \u0628\u0645\u0639\u0627\u0645\u0644 1.00: \u0625\u0646\u0647\u0645\u0627 \u0645\u062d\u062f\u062f \u062f\u064a\u0645\u0648\u063a\u0631\u0627\u0641\u064a \u0648\u0627\u062d\u062f \u0628\u0639\u064a\u0646\u0647\u060c \u064a\u062c\u0628 \u0627\u0644\u062a\u0639\u0627\u0645\u0644 \u0645\u0639\u0647 \u0643\u0643\u062a\u0644\u0629 \u0648\u0627\u062d\u062f\u0629.",
  "indicateurs.insight2.title": "\u0627\u0644\u0633\u0643\u0627\u0646 \u0627\u0644\u0634\u0628\u0627\u0628 \u0648\u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f: \u062a\u0648\u0623\u0645\u0627\u0646",
  "indicateurs.insight3.text": "\u0644\u0627 \u064a\u0638\u0647\u0631 \u0627\u0644\u062c\u0646\u0633 \u0641\u064a \u0623\u064a \u0645\u0643\u0627\u0646: \u0641\u0647\u0648 \u0644\u0627 \u064a\u0645\u064a\u0651\u0632 \u0628\u064a\u0646 \u0645\u0646 \u0647\u0645 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629. \u0643\u0630\u0644\u0643\u060c \u0639\u062f\u062f \u0627\u0644\u0645\u062f\u0627\u0631\u0633 \u0644\u064a\u0633 \u0627\u0644\u0645\u062d\u0631\u0643 \u0627\u0644\u0623\u0648\u0644\u060c \u0628\u0644 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0648\u0639\u0631\u0636 \u0627\u0644\u0645\u062d\u0627\u0636\u0631.",
  "indicateurs.insight3.title": "\u0645\u0627 \u0644\u0627 \u064a\u0631\u062a\u0628\u0637",
  "indicateurs.insight4.text": "\u0645\u0639\u0627\u0645\u0644\u0627\u062a r \u0627\u0644\u0628\u0627\u0644\u063a\u0629 1.00 \u0645\u0635\u062f\u0631\u0647\u0627 \u0645\u0624\u0634\u0631\u0627\u062a \u0628\u064f\u0646\u064a \u0623\u062d\u062f\u0647\u0627 \u0627\u0646\u0637\u0644\u0627\u0642\u064b\u0627 \u0645\u0646 \u0627\u0644\u0622\u062e\u0631: \u0646\u0633\u062a\u0628\u0639\u062f\u0647\u0627 \u0645\u0646 \u0627\u0644\u062a\u0648\u0635\u064a\u0627\u062a.",
  "indicateurs.insight4.title": "\u0627\u0646\u062a\u0628\u0647 \u0644\u0644\u0627\u0631\u062a\u0628\u0627\u0637\u0627\u062a \u0627\u0644\u062a\u0627\u0645\u0629",
