  "rapport.intro": "\u0648\u062b\u064a\u0642\u0629 A4 \u062c\u0627\u0647\u0632\u0629 \u0644\u0644\u0637\u0628\u0627\u0639\u0629: \u062e\u0644\u0627\u0635\u0629\u060c \u062a\u0631\u062a\u064a\u0628\u060c \u062a\u0631\u0643\u0651\u0632\u060c \u062a\u0635\u0646\u064a\u0641\u060c \u0645\u062d\u062f\u062f\u0627\u062a\u060c \u0633\u064a\u0646\u0627\u0631\u064a\u0648\u0647\u0627\u062a \u0648\u062a\u0648\u0635\u064a\u0627\u062a\u060c \u0645\u0648\u0636\u0651\u062d\u0629 \u0628\u0631\u0633\u0648\u0645 \u0628\u064a\u0627\u0646\u064a\u0629. \u0646\u0635\u064a\u062d\u0629: \u00ab\u062d\u0641\u0638 \u0628\u0635\u064a\u063a\u0629 PDF\u00bb \u0641\u064a \u0645\u0631\u0628\u0639 \u0627\u0644\u062d\u0648\u0627\u0631.",
