  "rapport.s1.lead3": "(26%). \u0645\u0646\u0647\u0645\u060c",
  "rapport.s1.lead4": "\u0623\u064a 33.1%. \u0646\u0635\u0641 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u064a\u062a\u0627\u0628\u0639\u0648\u0646 \u0627\u0644\u0645\u062d\u0636\u0631\u0629 (\u062a\u0642\u0644\u064a\u062f\u064a\u0629 \u0623\u0648 \u0642\u0631\u0622\u0646\u064a\u0629)\u061b \u0648\u0627\u0644\u0646\u0635\u0641 \u0627\u0644\u0622\u062e\u0631",
  "rapport.s1.lead5": ". \u0648\u0645\u0646 \u062b\u0645\u0651 \u0644\u0627 \u064a\u0633\u062a\u0648\u0639\u0628 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0631\u0633\u0645\u064a \u0633\u0648\u0649 \u0637\u0641\u0644 \u0648\u0627\u062d\u062f \u0645\u0646 \u0643\u0644 \u0637\u0641\u0644\u064a\u0646 \u0641\u064a \u0627\u0644\u062c\u064a\u0644 \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0645\u062f\u0631\u0633.",
