  "rapport.s1.m1.text": "\u0627\u0644\u0628\u0646\u0627\u062a \u0648\u0627\u0644\u0623\u0648\u0644\u0627\u062f \u0645\u062a\u0639\u0627\u062f\u0644\u0627\u0646 (32% \u0645\u0642\u0627\u0628\u0644 34%). \u063a\u064a\u0631 \u0623\u0646 \u0627\u0644\u0631\u064a\u0641 \u064a\u0636\u0627\u0639\u0641 \u0627\u0644\u062d\u0636\u0631 (42% \u0645\u0642\u0627\u0628\u0644 21%)\u060c \u0648\u062a\u0631\u0643\u0651\u0632 5 \u0648\u0644\u0627\u064a\u0627\u062a 72% \u0645\u0646 \u0627\u0644\u0645\u0634\u0643\u0644\u0629.",
