  "rapport.s1.m2.text": "44% \u0645\u0646 \u0641\u0626\u0629 6-9 \u0633\u0646\u0648\u0627\u062a \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0628\u0627\u0644\u0641\u0639\u0644 \u0645\u0642\u0627\u0628\u0644 23% \u0645\u0646 \u0641\u0626\u0629 10-14 \u0633\u0646\u0629: \u064a\u064f\u062d\u0633\u0645 \u0627\u0644\u0645\u0635\u064a\u0631 \u0639\u0646\u062f \u0627\u0644\u062f\u062e\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062a\u0645\u062f\u0631\u0633\u060c \u0644\u0627 \u0639\u0646\u062f \u0627\u0644\u062e\u0631\u0648\u062c.",
