  "rapport.s1.m3.text": "\u0646\u0635\u0641 \u0627\u0644\u0645\u0633\u062a\u0628\u0639\u062f\u064a\u0646 \u064a\u062a\u0645\u062f\u0631\u0633 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629. \u062a\u062d\u0648\u064a\u0644 \u0647\u0630\u0627 \u0627\u0644\u062e\u0632\u0627\u0646 \u0647\u0648 \u0627\u0644\u0623\u0643\u062b\u0631 \u0631\u0628\u062d\u064a\u0629 \u0628\u062d\u0644\u0648\u0644 2030 (\u221239% \u0645\u0646 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0628\u062a\u062d\u0648\u064a\u0644 50%).",
